<?php
require_once __DIR__.'/../config/conexao.php';require_once __DIR__.'/../includes/auth.php';exigir_conta_ativa($pdo,'leitor');
$st=$pdo->prepare('SELECT p.*,l.titulo,e.data_prevista,e.data_devolucao FROM pedido_emprestimo p JOIN livro l ON l.id_livro=p.id_livro LEFT JOIN emprestimo e ON e.id_emprestimo=p.id_emprestimo WHERE p.id_usuario=? ORDER BY p.id_pedido DESC');$st->execute([usuario_logado()['id_usuario']]);$pedidos=$st->fetchAll();
$st=$pdo->prepare("SELECT id_emprestimo FROM pedido_devolucao WHERE id_usuario=? AND status='pendente'");
$st->execute([usuario_logado()['id_usuario']]);
$devolucoes=array_fill_keys($st->fetchAll(PDO::FETCH_COLUMN),true);
cabecalho('Meus pedidos','meus');
?>
<div class="section-heading"><div><span class="eyebrow">ACOMPANHAMENTO</span><h2>Minhas solicitações</h2><p class="muted">Acompanhe a análise e os prazos de devolução.</p></div><a class="button button-primary" href="index.php">Explorar catálogo</a></div>
<div class="panel table-wrap"><?php if(!$pedidos): ?><div class="empty-state">Você ainda não solicitou livros.</div><?php else: ?><table><thead><tr><th>Livro</th><th>Solicitado em</th><th>Status</th><th>Devolução prevista</th><th>Ação</th></tr></thead><tbody><?php foreach($pedidos as $p): ?><tr><td class="strong"><?= e($p['titulo']) ?></td><td><?= e(date('d/m/Y H:i',strtotime($p['solicitado_em']))) ?></td><td><span class="status <?= $p['status']==='aprovado'?'status-ok':($p['status']==='recusado'?'status-late':'status-open') ?>"><?= e(ucfirst($p['status'])) ?></span><?php if($p['data_devolucao']): ?><small class="muted"> · Devolvido</small><?php endif; ?><?php if($p['observacao']): ?><small class="muted" style="display:block;max-width:220px;white-space:normal"><?= e($p['observacao']) ?></small><?php endif; ?></td><td><?= $p['data_prevista']?e(date('d/m/Y',strtotime($p['data_prevista']))):'—' ?></td><td><?php if($p['status']==='pendente'): ?><form method="post" action="cancelar.php" onsubmit="return confirm('Cancelar este pedido?')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$p['id_pedido'] ?>"><button class="link-button">Cancelar pedido</button></form><?php elseif($p['status']==='aprovado' && $p['id_emprestimo'] && !$p['data_devolucao']): ?>
<?php if(isset($devolucoes[$p['id_emprestimo']])): ?><span class="status status-open">Devolução solicitada</span>
<?php else: ?><form method="post" action="solicitar_devolucao.php" onsubmit="return confirm('Solicitar devolução? A baixa só ocorrerá após entrega e confirmação pela biblioteca.')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id_emprestimo" value="<?= (int)$p['id_emprestimo'] ?>"><button class="button button-small button-primary">Solicitar devolução</button></form><?php endif; ?>
<?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div><?php rodape(); ?>
